
CREATE TABLE IF NOT EXISTS campaigns (id UUID DEFAULT gen_random_uuid() PRIMARY KEY,name VARCHAR(100) NOT NULL,description TEXT DEFAULT '',password_hash VARCHAR(255) NOT NULL,dm_id UUID NOT NULL,is_active BOOLEAN DEFAULT true,max_players INT DEFAULT 6,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS characters (id UUID DEFAULT gen_random_uuid() PRIMARY KEY,user_id UUID NOT NULL,campaign_id UUID NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE,name VARCHAR(100) NOT NULL,race VARCHAR(50),class VARCHAR(50),background VARCHAR(50),level INT DEFAULT 1,alignment VARCHAR(30) DEFAULT 'true_neutral',ability_scores JSONB DEFAULT '{"str":10,"dex":10,"con":10,"int":10,"wis":10,"cha":10}',hit_points JSONB DEFAULT '{"max":10,"current":10,"temporary":0}',hit_dice JSONB DEFAULT '{"total":1,"current":1,"type":"d8"}',armor_class INT DEFAULT 10,speed INT DEFAULT 30,initiative INT DEFAULT 0,proficiency_bonus INT DEFAULT 2,equipment JSONB DEFAULT '[]',features JSONB DEFAULT '[]',traits JSONB DEFAULT '[]',spells JSONB DEFAULT '[]',notes TEXT DEFAULT '',token JSONB DEFAULT '{"color":"#4a90d9"}',created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS maps (id UUID DEFAULT gen_random_uuid() PRIMARY KEY,campaign_id UUID NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE,name VARCHAR(100) NOT NULL,image_url TEXT,grid_size INT DEFAULT 70,width INT DEFAULT 25,height INT DEFAULT 25,tokens JSONB DEFAULT '[]',fog_of_war JSONB DEFAULT '{}',is_active BOOLEAN DEFAULT false,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS chat_messages (id UUID DEFAULT gen_random_uuid() PRIMARY KEY,campaign_id UUID NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE,user_id UUID NOT NULL,username VARCHAR(50) NOT NULL,message TEXT NOT NULL,type VARCHAR(20) DEFAULT 'chat',created_at TIMESTAMPTZ DEFAULT NOW());
ALTER PUBLICATION supabase_realtime ADD TABLE chat_messages;
